window.futvizVista("perfil-ofensivo","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"perfil-ofensivo\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"perfil-ofensivo\"]={\"id\":\"perfil-ofensivo\",\"titulo\":\"Perfil ofensivo: xG90 vs. xA90\",\"bajada\":\"A la derecha, m\u00e1s xG por 90' (remata); arriba, m\u00e1s xA por 90' (crea). Abre con medios y delanteros.\",\"pregunta\":\"\u00bfQui\u00e9n remata y qui\u00e9n crea?\",\"tabla\":\"jugadores\",\"entidad\":\"jugadores\",\"x\":{\"col\":\"xG90\",\"label\":\"xG por 90'\",\"corto\":\"xG90\",\"dec\":2},\"y\":{\"col\":\"xA90\",\"label\":\"xA por 90'\",\"corto\":\"xA90\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tl\":\"Crean mucho pero rematan poco\",\"tr\":\"Crean y rematan mucho\",\"br\":\"Rematan mucho pero crean poco\",\"bl\":\"Crean y rematan poco\"},\"cuantil\":0.8},\"requiere\":[\"xG90\",\"xA90\"],\"subtitulo\":\"Jugadores con \u2265{min} min \u00b7 {temporada}\",\"filtros\":{\"posicion\":true,\"nivel\":true,\"sub21\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG90\",\"ayuda\":\"Ordenados por xG por 90'\"},{\"id\":\"y\",\"etiqueta\":\"xA90\",\"ayuda\":\"Ordenados por xA por 90'\"}],\"queMirar\":\"Qui\u00e9n remata (xG) y qui\u00e9n crea (xA), por 90 minutos.\\n- El eje horizontal mide cu\u00e1nto peligro genera con sus propios tiros (xG) y el vertical cu\u00e1nto genera para otros con sus pases (xA).\\n- Las l\u00edneas marcan el 20% m\u00e1s alto de cada eje: pasar una de ellas ya es destacar en esa faceta.\\n- Cada punto es un jugador de la temporada elegida; pasa el cursor para ver sus cifras y toca uno para resaltarlo.\",\"insight\":\"perfil\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"],\"posicionesIni\":[\"Medio\",\"Delantero\"]};</script>");